const REINFORCEMENT_SNAPSHOT_FIELDS = [
  "rebar_material_cost", "rebar_labor_cost", "rebar_labor_hours",
  "rebar_geometry_feet", "rebar_geometry_weight_lbs", "rebar_connection_count",
